// Extract message and context from webhook payload
const body = $input.first().json.body || $input.first().json;
const message = body.message || body.chatInput || '';
const url = body.url || '';
const sessionId = body.sessionId || 'seohub-' + Date.now();
const context = body.context || {};

// Build the agent input
return [{
  json: {
    chatInput: message + (url ? ' (URL: ' + url + ')' : ''),
    sessionId: sessionId,
    url: url,
    context: context
  }
}];

// Format the agent output for the client
const input = $input.first().json;
const output = input.output || input.text || JSON.stringify(input);

return [{
  json: {
    type: 'report',
    report: output,
    chips: ['full', 'speed', 'content', 'keywords', 'research'],
    isAr: /[؀-ۿ]/.test(output)
  }
}];
